func recordFileID(r *repo, path string) string {
	prefix := r.Config.Dir + "/"
	const suffix = ".yml"
	if len(path) <= len(prefix)+len(suffix) || path[:len(prefix)] != prefix || path[len(path)-len(suffix):] != suffix {
		return ""
	}
	id := path[len(prefix) : len(path)-len(suffix)]
	for i := 0; i < len(id); i++ {
		if id[i] == '/' {
			return ""
		}
	}
	return id
}

